guided.solution:
WITH invoices (invoice_no) AS (
  VALUES (1), (2), (3), (7), (8), (12), (13), (14)
)
SELECT invoice_no AS gap_after, next_no AS next_present, next_no - invoice_no - 1 AS missing_count
FROM (
  SELECT invoice_no, LEAD(invoice_no) OVER (ORDER BY invoice_no) AS next_no
  FROM invoices
) AS t
WHERE next_no - invoice_no > 1
ORDER BY gap_after;

