WITH loads (load_date) AS (
  VALUES (DATE '2024-03-01'), (DATE '2024-03-02'), (DATE '2024-03-03'), (DATE '2024-03-06'), (DATE '2024-03-07'), (DATE '2024-03-12')
)
SELECT load_date AS gap_start, load_date AS gap_end, 0 AS days_missing
FROM loads
ORDER BY load_date;

independent.solution:
WITH loads (load_date) AS (
  VALUES (DATE '2024-03-01'), (DATE '2024-03-02'), (DATE '2024-03-03'), (DATE '2024-03-06'), (DATE '2024-03-07'), (DATE '2024-03-12')
)
SELECT load_date + 1 AS gap_start, next_date - 1 AS gap_end, next_date - load_date - 1 AS days_missing
FROM (
  SELECT load_date, LEAD(load_date) OVER (ORDER BY load_date) AS next_date
  FROM loads
) AS t
WHERE next_date - load_date > 1
ORDER BY gap_start;
